-- A build loads its entries in key order, a NULL part last: of two oversized rows, the one
-- holding `a` is named though the one holding NULL is read first.
-- @setup
CREATE TABLE t (a text, b text);
INSERT INTO t VALUES (NULL, ''), ('a', '');
-- @test
-- @expect-error: the non-NULL row sorts first
-- @expect-message
-- @profile-lock
CREATE INDEX t_i ON t (a, b);
